-- 읽기 전용 국소 점검. 전체 통합 지문은 이번 릴리스의 통합 점검 파일을 함께 사용한다.
WITH t AS(SELECT oid,relrowsecurity FROM pg_class WHERE relnamespace='workhub'::regnamespace AND relname IN('school_data_policies','school_data_previews','school_data_requests','school_data_revisions') AND relkind='r'),
f AS(SELECT oid,proowner,prosecdef,proconfig FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('workhub_school_data_get','workhub_school_data_preview','workhub_school_data_commit','workhub_school_data_close'))
SELECT 'P10-04-01' no,'설치 기록 2개' item,CASE WHEN(SELECT count(*) FROM workhub_private.p10_installs WHERE batch IN('P10-01','P10-02'))=2 THEN 'ok' ELSE 'FAIL' END status
UNION ALL SELECT 'P10-04-02','신규 표 4개 RLS·API 권한 없음',CASE WHEN(SELECT count(*) FROM t)=4 AND NOT EXISTS(SELECT 1 FROM t WHERE NOT relrowsecurity OR has_table_privilege('anon',oid,'SELECT,INSERT,UPDATE,DELETE') OR has_table_privilege('authenticated',oid,'SELECT,INSERT,UPDATE,DELETE')) THEN 'ok' ELSE 'FAIL' END
UNION ALL SELECT 'P10-04-03','RPC 4개 소유자·고정 search_path·실행 역할',CASE WHEN(SELECT count(*) FROM f)=4 AND NOT EXISTS(SELECT 1 FROM f WHERE proowner<>'postgres'::regrole OR NOT prosecdef OR NOT('search_path=""'=ANY(proconfig)) OR has_function_privilege('anon',oid,'EXECUTE') OR NOT has_function_privilege('authenticated',oid,'EXECUTE')) THEN 'ok' ELSE 'FAIL' END
UNION ALL SELECT 'P10-04-04','내부 함수 API 실행 0',CASE WHEN NOT EXISTS(SELECT 1 FROM pg_proc WHERE pronamespace='workhub_private'::regnamespace AND proname LIKE 'p10_%' AND(has_function_privilege('anon',oid,'EXECUTE') OR has_function_privilege('authenticated',oid,'EXECUTE'))) THEN 'ok' ELSE 'FAIL' END
UNION ALL SELECT 'P10-04-05','정정 전후 원장 보호 3개·기존 쓰기 보호 16개',CASE WHEN(SELECT count(*) FROM pg_trigger WHERE tgfoid='workhub_private.p10_entity_guard()'::regprocedure AND tgenabled='O')=3 AND(SELECT count(*) FROM pg_trigger WHERE tgfoid='workhub_private.p10_active_write()'::regprocedure AND tgenabled='O')=16 THEN 'ok' ELSE 'FAIL' END
UNION ALL SELECT 'P10-04-06','미래 담당 중복 보호',CASE WHEN EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='workhub.course_assignments'::regclass AND tgfoid='workhub_private.p10_assignment_overlap()'::regprocedure AND tgenabled='O') AND NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='workhub.course_assignments'::regclass AND conname='course_assignments_no_overlap') THEN 'ok' ELSE 'FAIL' END
UNION ALL SELECT 'P10-04-07','전후 원장·원요청 변경 금지',CASE WHEN(SELECT count(*) FROM pg_trigger WHERE tgname='p10_immutable' AND tgenabled='O' AND tgfoid='workhub_private.forbid_change()'::regprocedure)=4 THEN 'ok' ELSE 'FAIL' END
UNION ALL SELECT 'P10-04-08','보호된 T1 원천·P5 기록/명부 함수',CASE WHEN(SELECT count(*) FROM pg_proc WHERE pronamespace='workhub_private'::regnamespace AND proname IN('t1_build','p5_course_get','p5_course_dto','p5_course_snapshot','p5_roster_import') AND prosrc LIKE '%workhub_private.p10_state%')=5 THEN 'ok' ELSE 'FAIL' END
UNION ALL SELECT 'P10-04-09','기능 활성화 상태',CASE WHEN EXISTS(SELECT 1 FROM workhub.school_data_policies WHERE active) THEN 'info' ELSE 'info' END
ORDER BY no;
